'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useState, useEffect } from 'react';
import { Menu, X } from 'lucide-react';
import { ThemeToggle } from './ThemeToggle';

export default function Navbar() {
  const pathname = usePathname();
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Home', href: '/' },
    { name: 'About', href: '/about' },
    { name: 'Services', href: '/services' },
    { name: 'Contact', href: '/contact' },
  ];

  return (
    <div className="fixed bottom-8 inset-x-0 z-50 flex justify-center px-4">
      <nav className={`
        relative w-full max-w-2xl transition-all duration-500 ease-in-out
        bg-[#121212]/80 backdrop-blur-xl border border-white/5 py-2 px-2 rounded-full shadow-2xl
      `}>
        <div className="flex items-center justify-between gap-1">
          {/* Logo - simplified for bottom bar */}
          <Link href="/" className="ml-2 group flex items-center gap-2">
            <div className="w-8 h-8 bg-[#800000] rounded-full flex items-center justify-center text-white font-bold text-sm group-hover:scale-110 transition-transform duration-300 shadow-[0_0_15px_rgba(128,0,0,0.4)]">
              S
            </div>
          </Link>

          {/* Desktop Navigation */}
          <div className="flex items-center gap-1">
            {navLinks.map((link) => {
              const isActive = pathname === link.href;
              return (
                <Link
                  key={link.name}
                  href={link.href}
                  className={`px-4 py-2 rounded-full text-xs font-semibold transition-all duration-300
                    ${isActive
                      ? 'bg-[#800000] text-white shadow-[0_0_20px_rgba(128,0,0,0.3)]'
                      : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
                >
                  {link.name}
                </Link>
              );
            })}
          </div>

          <div className="flex items-center gap-1">
            <Link
              href="/admin/login"
              className="px-4 py-2 bg-white text-[#0B0B0F] text-xs font-bold rounded-full hover:bg-gray-200 transition-all duration-300"
            >
              Login
            </Link>
          </div>
        </div>
      </nav>
    </div>
  );
}

